Local Ltac Z.euclidean_division_equations_cleanup ::= idtac.

Import ListNotations.
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Local Ltac transport_chunks segs m a bs ::= transport_chunks_fast segs m a bs.
Local Ltac footprint_after_store segs m a bs ::= footprint_after_store_fast segs m a bs.
Local Ltac mem_after_store ::= mem_after_store_fast.

Definition ivfscanf_entry : Z := 0xb6ad0.
Notation IVFSCANF_DEPTH := 3008%Z (only parsing).   (* [comment removed for export] *)

(* [comment removed for export] *)
Definition real_vfscanf_cell (m : mem) : Prop := ro_cells asegs m 0x213758 [C8 (Z_to_bv 64 vfscanf_entry)].

(* [comment removed for export] *)
Ltac tr_all MUc WMc :=
  lazymatch type of MUc with munch ?W ?m0 ?m2 =>
    repeat match goal with
    | H : rw_cells asegs m0 ?A ?cs |- _ =>
        first [ let TR := fresh "TR" in
                pose proof (rw_cells_transport asegs W m0 m2 A cs H MUc WMc
                  ltac:(cbn [disjoint_from cells_size csize Nat.add Z.of_nat Pos.of_succ_nat Pos.succ length]; repeat split; lia)) as TR;
                clear H; rename TR into H
              | idtac "tr_all: dropping" H; clear H ]
    | H : ro_cells asegs m0 ?A ?cs |- _ =>
        first [ let TR := fresh "TR" in
                pose proof (ro_cells_transport asegs W m0 m2 A cs H MUc
                  ltac:(cbn [disjoint_from cells_size csize Nat.add Z.of_nat Pos.of_succ_nat Pos.succ length]; repeat split; lia)) as TR;
                clear H; rename TR into H
              | idtac "tr_all: dropping" H; clear H ]
    end
  end.

Section WithHyps.
Hypothesis RIP : rip_stmt.
Hypothesis VF : vfscanf_dd_stmt.

Definition ivfscanf_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (f p1 p2 d1 d2 : Z) (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists (t0' t1' t2' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' : word) (m' : mem) (st' : sfst),
    ms' = MS (mkR ra sp gp tp t0' t1' t2' s0 s1 (Z_to_bv 64 2) a1' a2' a3' a4' a5' a6' a7' s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3' t4' t5' t6')
             F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch [(f, f + 232); (bv_unsigned sp - IVFSCANF_DEPTH, bv_unsigned sp); (p1, p1 + 4); (p2, p2 + 4)] m m'
    /\ wmono asegs m m' /\ mem_inv asegs m' /\ stk asegs m' lo (bv_unsigned sp)
    /\ rw_cells asegs m' f (sfile st')
    /\ rw_cells asegs m' p1 [C4 (Z_to_bv 64 d1)] /\ rw_cells asegs m' p2 [C4 (Z_to_bv 64 d2)].

(* [comment removed for export] *)
Theorem ivfscanf_spec : forall ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (f s ap p1 p2 : Z) (tok : list Z) (extra : list byte) (d1 d2 : Z) (j1 j2 : list byte) (g : word) (lo : Z),
  a0 = Z_to_bv 64 f -> a1 = Z_to_bv 64 SSCANF_FMT -> a2 = Z_to_bv 64 ap ->
  rw_cells asegs m f (sfile (sf_init s)) -> bv_unsigned sp <= f -> f + 232 <= 2^47 ->
  rw_cells asegs m ap [C8 (Z_to_bv 64 p1); C8 (Z_to_bv 64 p2)] -> bv_unsigned sp <= ap -> ap + 16 <= 2^47 ->
  (f + 232 <= ap \/ ap + 16 <= f) ->
  In (tok, (d1, d2)) SSCANF_TOKENS -> bytes_at asegs m s (map (Z_to_bv 8) tok ++ extra) -> s mod 16 = 1 ->
  Z.of_nat (length tok) + Z.of_nat (length extra) = 7 -> 0 < s -> s + 7 <= lo ->
  chk_ok m s (Z.of_nat (length tok)) -> chk_ok m (s + Z.of_nat (length tok) - 1) 1 ->
  chk_ok m (bv_unsigned sp - 609) 1 -> chk_ok m (bv_unsigned sp - 689) 1 ->
  rw_cells asegs m p1 [CB 4 j1] -> rw_cells asegs m p2 [CB 4 j2] -> 0 < p1 -> 0 < p2 ->
  (p1 + 4 <= p2 \/ p2 + 4 <= p1) -> p1 + 4 <= lo -> p2 + 4 <= lo ->
  (s + 7 <= p1 \/ p1 + 4 <= s) -> (s + 7 <= p2 \/ p2 + 4 <= s) -> rt3_apart p1 -> rt3_apart p2 ->
  chk_ok m SSCANF_FMT 6 -> chk_ok m p1 4 -> chk_ok m p2 4 -> p1 mod 8 = 0 -> p2 mod 8 = 0 ->
  m2s_cells m -> icells_mc m -> icells m -> icells_sn m -> ssp_cells m g -> real_vfscanf_cell m ->
  stk asegs m lo (bv_unsigned sp) -> lo <= bv_unsigned sp - IVFSCANF_DEPTH -> kHighShadowEnd + 8 <= lo -> (bv_unsigned sp) mod 16 = 0 ->
  mem_inv asegs m ->
  evt asegs (ivfscanf_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc f p1 p2 d1 d2 lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 ivfscanf_entry) fc None m (seg_rom asegs)).
Proof using RIP VF.
