Definition isscanf_entry : Z := 0xb6b80.
Notation ISSCANF_DEPTH := 3408%Z (only parsing).   (* [comment removed for export] *)

(* [comment removed for export] *)
Definition real_vsscanf_cell (m : mem) : Prop := ro_cells asegs m 0x213750 [C8 (Z_to_bv 64 vsscanf_entry)].

Definition isscanf_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (p1 p2 d1 d2 : Z) (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists (t0' t1' t2' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' : word) (m' : mem),
    ms' = MS (mkR ra sp gp tp t0' t1' t2' s0 s1 (Z_to_bv 64 2) a1' a2' a3' a4' a5' a6' a7' s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3' t4' t5' t6')
             F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch [(bv_unsigned sp - ISSCANF_DEPTH, bv_unsigned sp); (p1, p1 + 4); (p2, p2 + 4)] m m'
    /\ wmono asegs m m' /\ mem_inv asegs m' /\ stk asegs m' lo (bv_unsigned sp)
    /\ rw_cells asegs m' p1 [C4 (Z_to_bv 64 d1)] /\ rw_cells asegs m' p2 [C4 (Z_to_bv 64 d2)].

(* [comment removed for export] *)
Theorem isscanf_spec : forall ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (s p1 p2 : Z) (tok : list Z) (extra : list byte) (d1 d2 : Z) (j1 j2 : list byte) (g : word) (lo : Z),
  a0 = Z_to_bv 64 s -> a1 = Z_to_bv 64 SSCANF_FMT -> a2 = Z_to_bv 64 p1 -> a3 = Z_to_bv 64 p2 ->
  In (tok, (d1, d2)) SSCANF_TOKENS -> bytes_at asegs m s (map (Z_to_bv 8) tok ++ extra) -> s mod 16 = 1 ->
  Z.of_nat (length tok) + Z.of_nat (length extra) = 7 -> 0 < s -> s + 7 <= lo ->
  chk_ok m s (Z.of_nat (length tok)) -> chk_ok m (s + Z.of_nat (length tok) - 1) 1 ->
  chk_ok m (bv_unsigned sp - 1009) 1 -> chk_ok m (bv_unsigned sp - 1089) 1 -> chk_ok m (bv_unsigned sp - 392) 232 ->
  rw_cells asegs m p1 [CB 4 j1] -> rw_cells asegs m p2 [CB 4 j2] -> 0 < p1 -> 0 < p2 ->
  (p1 + 4 <= p2 \/ p2 + 4 <= p1) -> p1 + 4 <= lo -> p2 + 4 <= lo ->
  (s + 7 <= p1 \/ p1 + 4 <= s) -> (s + 7 <= p2 \/ p2 + 4 <= s) -> rt3_apart p1 -> rt3_apart p2 ->
  chk_ok m SSCANF_FMT 6 -> chk_ok m p1 4 -> chk_ok m p2 4 -> p1 mod 8 = 0 -> p2 mod 8 = 0 ->
  m2s_cells m -> icells_mc m -> icells m -> icells_sn m -> icells_ms m -> ssp_cells m g -> real_vfscanf_cell m -> real_vsscanf_cell m ->
  stk asegs m lo (bv_unsigned sp) -> lo <= bv_unsigned sp - ISSCANF_DEPTH -> kHighShadowEnd + 8 <= lo -> (bv_unsigned sp) mod 16 = 0 ->
  bv_unsigned sp <= 2^47 ->
  mem_inv asegs m ->
  evt asegs (isscanf_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc p1 p2 d1 d2 lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
